#!/usr/bin/env python3
"""统计 CSV 文件中每一列的非空值数量。

用法:
    python count_nonempty.py data.csv
    python count_nonempty.py data.csv --delimiter ';' --encoding gbk
"""

from __future__ import annotations

import argparse
import csv
import sys
from collections import Counter


def count_nonempty(path: str, delimiter: str = ",", encoding: str = "utf-8-sig") -> tuple[list[str], Counter]:
    with open(path, newline="", encoding=encoding) as fh:
        reader = csv.reader(fh, delimiter=delimiter)
        try:
            header = next(reader)
        except StopIteration:
            return [], Counter()

        counts: Counter = Counter()
        for row in reader:
            for i, value in enumerate(row):
                if i >= len(header):
                    # 行宽超出表头，按位置补充列名
                    header.append(f"column_{i + 1}")
                if value.strip():
                    counts[i] += 1

        for i in range(len(header)):
            counts[i]  # 触发键存在
        return header, counts


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description="统计 CSV 每一列的非空值数量")
    parser.add_argument("csv_file", help="CSV 文件路径")
    parser.add_argument("--delimiter", default=",", help="字段分隔符，默认逗号")
    parser.add_argument("--encoding", default="utf-8-sig", help="文件编码，默认 utf-8-sig")
    args = parser.parse_args(argv)

    try:
        header, counts = count_nonempty(args.csv_file, args.delimiter, args.encoding)
    except OSError as exc:
        print(f"无法读取文件: {exc}", file=sys.stderr)
        return 1

    if not header:
        print("文件为空，没有可统计的列。")
        return 0

    width = max(len(name) for name in header)
    print(f"{'列名'.ljust(width)}  非空值数量")
    print(f"{'-' * width}  ------------")
    for i, name in enumerate(header):
        print(f"{name.ljust(width)}  {counts[i]}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

